def compute(vars):
    total_percentage = vars["v1"] + vars["v2"]
    return {
        "value": total_percentage,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "total_percentage": total_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
